dashboard.definition:
{
  "title": "Sites",
  "description": "Site health from New Central: worst sites first, trend and all sites.",
  "inputs": {
    "input_time": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "tr",
        "defaultValue": "-24h,now"
      }
    },
    "input_site": {
      "type": "input.text",
      "title": "Site (wildcard)",
      "options": {
        "token": "site",
        "defaultValue": "*"
      }
    }
  },
  "dataSources": {
    "ds_n": {
      "type": "ds.search",
      "name": "Sites",
      "options": {
        "query": "`aruba_central_index` sourcetype=\"aruba:central:site_health\" earliest=-30m\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| stats latest(health.groups{}.name) as hn latest(health.groups{}.value) as hv latest(devices.count) as devices latest(clients.count) as clients latest(alerts.totalCount) as alerts latest(reasons{}.reason) as reasons latest(_time) as last_poll by id siteName\n| eval poor=tonumber(mvindex(hv,mvfind(hn,\"Poor\"))), fair=tonumber(mvindex(hv,mvfind(hn,\"Fair\"))), good=tonumber(mvindex(hv,mvfind(hn,\"Good\")))\n| eval poor=coalesce(poor,0), fair=coalesce(fair,0), good=coalesce(good,0)\n| stats count"
      }
    },
    "ds_poor": {
      "type": "ds.search",
      "name": "Sites with poor health",
      "options": {
        "query": "`aruba_central_index` sourcetype=\"aruba:central:site_health\" earliest=-30m\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| stats latest(health.groups{}.name) as hn latest(health.groups{}.value) as hv latest(devices.count) as devices latest(clients.count) as clients latest(alerts.totalCount) as alerts latest(reasons{}.reason) as reasons latest(_time) as last_poll by id siteName\n| eval poor=tonumber(mvindex(hv,mvfind(hn,\"Poor\"))), fair=tonumber(mvindex(hv,mvfind(hn,\"Fair\"))), good=tonumber(mvindex(hv,mvfind(hn,\"Good\")))\n| eval poor=coalesce(poor,0), fair=coalesce(fair,0), good=coalesce(good,0)\n| where poor>0 | stats count"
      }
    },
    "ds_cl": {
      "type": "ds.search",
      "name": "Clients",
      "options": {
        "query": "`aruba_central_index` sourcetype=\"aruba:central:site_health\" earliest=-30m\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| stats latest(health.groups{}.name) as hn latest(health.groups{}.value) as hv latest(devices.count) as devices latest(clients.count) as clients latest(alerts.totalCount) as alerts latest(reasons{}.reason) as reasons latest(_time) as last_poll by id siteName\n| eval poor=tonumber(mvindex(hv,mvfind(hn,\"Poor\"))), fair=tonumber(mvindex(hv,mvfind(hn,\"Fair\"))), good=tonumber(mvindex(hv,mvfind(hn,\"Good\")))\n| eval poor=coalesce(poor,0), fair=coalesce(fair,0), good=coalesce(good,0)\n| stats sum(clients) as clients"
      }
    },
    "ds_al": {
      "type": "ds.search",
      "name": "Alerts",
      "options": {
        "query": "`aruba_central_index` sourcetype=\"aruba:central:site_health\" earliest=-30m\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| stats latest(health.groups{}.name) as hn latest(health.groups{}.value) as hv latest(devices.count) as devices latest(clients.count) as clients latest(alerts.totalCount) as alerts latest(reasons{}.reason) as reasons latest(_time) as last_poll by id siteName\n| eval poor=tonumber(mvindex(hv,mvfind(hn,\"Poor\"))), fair=tonumber(mvindex(hv,mvfind(hn,\"Fair\"))), good=tonumber(mvindex(hv,mvfind(hn,\"Good\")))\n| eval poor=coalesce(poor,0), fair=coalesce(fair,0), good=coalesce(good,0)\n| stats sum(alerts) as alerts"
      }
    },
    "ds_rank": {
      "type": "ds.search",
      "name": "Worst sites",
      "options": {
        "query": "`aruba_central_index` sourcetype=\"aruba:central:site_health\" earliest=-30m\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| stats latest(health.groups{}.name) as hn latest(health.groups{}.value) as hv latest(devices.count) as devices latest(clients.count) as clients latest(alerts.totalCount) as alerts latest(reasons{}.reason) as reasons latest(_time) as last_poll by id siteName\n| eval poor=tonumber(mvindex(hv,mvfind(hn,\"Poor\"))), fair=tonumber(mvindex(hv,mvfind(hn,\"Fair\"))), good=tonumber(mvindex(hv,mvfind(hn,\"Good\")))\n| eval poor=coalesce(poor,0), fair=coalesce(fair,0), good=coalesce(good,0)\n| where devices>0\n| eval Reasons=mvjoin(reasons,\", \")\n| sort - poor - alerts\n| table siteName poor fair good devices clients alerts Reasons\n| rename siteName as Site, poor as \"Poor %\", fair as \"Fair %\", good as \"Good %\", devices as Devices, clients as Clients, alerts as Alerts"
      }
    },
    "ds_trend": {
      "type": "ds.search",
      "name": "Poor health trend",
      "options": {
        "query": "`aruba_central_index` sourcetype=\"aruba:central:site_health\"\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| eval poor=tonumber(mvindex('health.groups{}.value',mvfind('health.groups{}.name',\"Poor\"))), devices='devices.count'\n| where devices>0\n| timechart minspan=15m max(poor) by siteName limit=8"
      }
    },
    "ds_sites": {
      "type": "ds.search",
      "name": "Sites",
      "options": {
        "query": "`aruba_central_index` sourcetype=\"aruba:central:site_health\" earliest=-30m\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| stats latest(health.groups{}.name) as hn latest(health.groups{}.value) as hv latest(devices.count) as devices latest(clients.count) as clients latest(alerts.totalCount) as alerts latest(reasons{}.reason) as reasons latest(_time) as last_poll by id siteName\n| eval poor=tonumber(mvindex(hv,mvfind(hn,\"Poor\"))), fair=tonumber(mvindex(hv,mvfind(hn,\"Fair\"))), good=tonumber(mvindex(hv,mvfind(hn,\"Good\")))\n| eval poor=coalesce(poor,0), fair=coalesce(fair,0), good=coalesce(good,0)\n| eval last_poll=strftime(last_poll,\"%Y-%m-%d %H:%M:%S\")\n| table siteName id clients devices alerts last_poll\n| sort - clients\n| rename siteName as Site, id as \"Site ID\", clients as Clients, devices as Devices, alerts as Alerts, last_poll as \"Last poll\""
      }
    }
  },
  "visualizations": {
    "v_n": {
      "type": "splunk.singlevalue",
      "title": "Sites",
      "dataSources": {
        "primary": "ds_n"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "v_poor": {
      "type": "splunk.singlevalue",
      "title": "Sites with poor health",
      "dataSources": {
        "primary": "ds_poor"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "backgroundColor": "> majorValue | rangeValue(cfg)",
        "majorColor": "#FFFFFF",
        "unitColor": "#FFFFFF",
        "trendColor": "#FFFFFF",
        "sparklineStrokeColor": "#FFFFFF"
      },
      "context": {
        "cfg": [
          {
            "value": "#53A051",
            "to": 1
          },
          {
            "value": "#D99B1E",
            "from": 1
          }
        ]
      }
    },
    "v_cl": {
      "type": "splunk.singlevalue",
      "title": "Clients",
      "dataSources": {
        "primary": "ds_cl"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(cfg)"
      },
      "context": {
        "cfg": [
          {
            "value": "#1182F3"
          }
        ]
      }
    },
    "v_al": {
      "type": "splunk.singlevalue",
      "title": "Alerts reported by sites",
      "dataSources": {
        "primary": "ds_al"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(cfg)"
      },
      "context": {
        "cfg": [
          {
            "value": "#53A051",
            "to": 1
          },
          {
            "value": "#F8BE34",
            "from": 1
          }
        ]
      }
    },
    "v_rank": {
      "type": "splunk.table",
      "title": "Sites ranked by poor health (click a row for the site overview)",
      "dataSources": {
        "primary": "ds_rank"
      },
      "options": {
        "count": 8,
        "columnFormat": {
          "Poor %": {
            "rowBackgroundColors": "> table | seriesByName(\"Poor %\") | rangeValue(r0)",
            "rowColors": "> table | seriesByName(\"Poor %\") | rangeValue(r0t)"
          },
          "Fair %": {
            "rowBackgroundColors": "> table | seriesByName(\"Fair %\") | rangeValue(r1)",
            "rowColors": "> table | seriesByName(\"Fair %\") | rangeValue(r1t)"
          },
          "Alerts": {
            "rowBackgroundColors": "> table | seriesByName(\"Alerts\") | rangeValue(r2)",
            "rowColors": "> table | seriesByName(\"Alerts\") | rangeValue(r2t)"
          }
        }
      },
      "context": {
        "r0": [
          {
            "value": "transparent",
            "to": 1
          },
          {
            "value": "#DC4E41",
            "from": 1
          }
        ],
        "r0t": [
          {
            "value": "#FFFFFF",
            "to": 1
          },
          {
            "value": "#FFFFFF",
            "from": 1
          }
        ],
        "r1": [
          {
            "value": "transparent",
            "to": 1
          },
          {
            "value": "#D99B1E",
            "from": 1
          }
        ],
        "r1t": [
          {
            "value": "#FFFFFF",
            "to": 1
          },
          {
            "value": "#FFFFFF",
            "from": 1
          }
        ],
        "r2": [
          {
            "value": "transparent",
            "to": 1
          },
          {
            "value": "#D99B1E",
            "from": 1
          }
        ],
        "r2t": [
          {
            "value": "#FFFFFF",
            "to": 1
          },
          {
            "value": "#FFFFFF",
            "from": 1
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/aruba_network_insights/overview?form.site=$row.Site.value$",
            "newTab": false
          }
        }
      ]
    },
    "v_trend": {
      "type": "splunk.line",
      "title": "Poor health over time (top 8 sites)",
      "dataSources": {
        "primary": "ds_trend"
      },
      "options": {
        "legendDisplay": "bottom",
        "x": "> primary | seriesByName('_time')",
        "y": "> primary | frameBySeriesTypes('number')",
        "nullValueDisplay": "connect",
        "lineWidth": 2
      }
    },
    "v_sites": {
      "type": "splunk.table",
      "title": "All sites (click a row for the site's alerts)",
      "dataSources": {
        "primary": "ds_sites"
      },
      "options": {
        "count": 10
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/aruba_network_insights/alerts?form.site=$row.Site.value$&form.severity=*",
            "newTab": false
          }
        }
      ]
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$tr.earliest$",
            "latest": "$tr.latest$"
          }
        }
      }
    }
  },
  "layout": {
    "globalInputs": [
      "input_time",
      "input_site"
    ],
    "layoutDefinitions": {
      "layout_1": {
        "type": "grid",
        "options": {
          "width": 1200
        },
        "structure": [
          {
            "item": "v_n",
            "type": "block",
            "position": {
              "x": 0,
              "y": 0,
              "w": 300,
              "h": 140
            }
          },
          {
            "item": "v_poor",
            "type": "block",
            "position": {
              "x": 300,
              "y": 0,
              "w": 300,
              "h": 140
            }
          },
          {
            "item": "v_cl",
            "type": "block",
            "position": {
              "x": 600,
              "y": 0,
              "w": 300,
              "h": 140
            }
          },
          {
            "item": "v_al",
            "type": "block",
            "position": {
              "x": 900,
              "y": 0,
              "w": 300,
              "h": 140
            }
          },
          {
            "item": "v_rank",
            "type": "block",
            "position": {
              "x": 0,
              "y": 140,
              "w": 1200,
              "h": 340
            }
          },
          {
            "item": "v_trend",
            "type": "block",
            "position": {
              "x": 0,
              "y": 480,
              "w": 1200,
              "h": 300
            }
          },
          {
            "item": "v_sites",
            "type": "block",
            "position": {
              "x": 0,
              "y": 780,
              "w": 1200,
              "h": 340
            }
          }
        ]
      }
    },
    "options": {
      "submitButton": false
    },
    "tabs": {
      "items": [
        {
          "layoutId": "layout_1",
          "label": "Sites"
        }
      ]
    }
  }
}
